import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百七十一章 不要被扰乱心念","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/271第二百七十一章 不要被扰乱心念-法理.md","filePath":"meditation/巴利文大藏经/271第二百七十一章 不要被扰乱心念-法理.md"}'),o={name:"meditation/巴利文大藏经/271第二百七十一章 不要被扰乱心念-法理.md"};function r(n,t,i,s,d,c){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="第二百七十一章-不要被扰乱心念" tabindex="-1">第二百七十一章 不要被扰乱心念 <a class="header-anchor" href="#第二百七十一章-不要被扰乱心念" aria-label="Permalink to &quot;第二百七十一章 不要被扰乱心念&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部22相应62经/言语道经(蕴相应/蕴篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人），不要被三种外教修行人反驳、指责的言语表现形式，取出的名字称呼，建立、创立的观点见解扰乱心念。是那种三种言语、名称、见解呢？</p><p>比丘们！对于过去已经变化的物质事物、物质身体，对于过去已经灭尽的物质事物、物质身体，用言语描述这些过去的物质事物、物质身体；取出名字称呼这些过去的物质事物、物质身体；以这些过去的物质事物、物质身体为基础建立、创立的观点见解。</p><p>对于过去已经变化的感受、念想、行为、认识、分别、判断，对于过去已经灭尽的感受、念想、行为、认识、分别、判断，用言语描述这些过去的感受、念想、行为、认识、分别、判断；取出名字称呼这些过去的感受、念想、行为、认识、分别、判断；以这些过去的感受、念想、行为、认识、分别、判断为基础建立、创立的观点见解。</p><p>比丘们！对于未来还没有生起的物质事物、物质身体，对于未来还没有出现的物质事物、物质身体，用言语描述这些未来的物质事物、物质身体；取出名字称呼这些未来的物质事物、物质身体；以这些未来的物质事物、物质身体为基础建立、创立的观点见解。</p><p>对于未来还没有生起的感受、念想、行为、认识、分别、判断，对于未来还没有出现的感受、念想、行为、认识、分别、判断，用言语描述这些未来的感受、念想、行为、认识、分别、判断；取出名字称呼这些未来的感受、念想、行为、认识、分别、判断；以这些未来的感受、念想、行为、认识、分别、判断为基础建立、创立的观点见解。</p><p>比丘们！对于现在已经生起的物质事物、物质身体，对于现在已经出现的物质事物、物质身体，用言语描述这些现在的物质事物、物质身体；取出名字称呼这些现在的物质事物、物质身体；以这些现在的物质事物、物质身体为基础建立、创立的观点见解。</p><p>对于现在已经生起的感受、念想、行为、认识、分别、判断，对于现在已经出现的感受、念想、行为、认识、分别、判断，用言语描述这些现在的感受、念想、行为、认识、分别、判断；取出名字称呼这些现在的感受、念想、行为、认识、分别、判断；以这些现在的感受、念想、行为、认识、分别、判断为基础建立、创立的观点见解。</p><p>比丘们！世间一切的物质事物、物质身体、感受、念想、行为、认识、分别、判断，描述它们的语言，它们名字的称谓，由它们建立起来的观点见解都是世间的人、众生由自己的念想、思想创建出来的，物质事物、物质身体、感受、念想、行为、认识、分别、判断本来是没有名字的，没有言语描述的，没有观点和见解的。这些言语、名字、观点都是世间的人、众生用内心的念想、思想分别、区别出来的。不管是那些认为世间一切事物都是没有原因，没有条件就生起、形成、存续、发展、衰败、灭亡、消失的无因论者，还是那些没有善恶是非，认为身体行为做恶事，口说恶语，内心生起恶念的恶行不会导致痛苦的恶报，认为身体行为做善事，口说善语，内心生起善念的善行不会获得快乐的福报，不认为有善恶因果报应存在的不作业论者，甚至于那些认为世间根本就不存在，认为世间完全是虚假、不真实的虚无论者，包括如来的正法在内，这些法都是由过去、现在、未来的物质事物、物质身体、感受、念想、行为、认识、分别、判断生起的念想、思想建立、创立出来的，当内心不生起任何念想的时候，就没有这些言语、名字、见解的存在。虽然如此，世间还是会按它既有的规律、规则运行，就如同下雨的时候，虽然你们不知道正在下雨，内心没有生起下雨的念想，可是雨仍然会继续的下，不会因为你们没有生起念想就不下雨，世间的一切的事物都是会在一定的前提条件下生起、形成、存续、发展、衰败、灭亡、消失的，既不能认为它们真实永远存在，也不能认为他们是虚假不存在的，条件出现了它们就会生起、形成、存续、发展、衰败、灭亡、消失。不可执着和挂念这些缘生缘灭的世间事物。至于善恶行为导致的善恶结果，也是显而易见的事情，自己不想被恶行对待，别人也同样不想被恶行对待，自己愿意接受善行，别人也同样愿意接受善行，就如同种植蔬菜和稻谷，只有认真细心的耕耘、施肥、浇灌、善待这些种植下去的幼苗，在合适的气候条件下才能获得丰收。不耕耘、不施肥、不浇灌这些幼苗，甚至于踩踏这些幼苗，拔出这些幼苗，恶意毁坏这些幼苗那是无法获得丰收的。想要获得什么就要先去种植下什么，对别人善行、善言、善念的付出，就会获得善行、善言、善念的回报，就如同种植蔬菜和稻谷一样。</p><p>比丘们！如来的正法不过是教导众生除灭烦恼和痛苦暂时安立出来的修行方法而已。如来的正法也是清净的烦恼，不过是用清净的烦恼去除灭污秽的烦恼，念想的生起就是烦恼的生起。因此你们对于这些外教修行人的反驳、指责，不要生气，不要愤怒，不要畏惧，你们对于他们的反驳、指责不要生起喜怒哀乐等等的念想，你们不要去反驳、指责他们的观点见解，你们要心平气和的给他们讲说如来的正法，你们要如实对他们讲解如来的正法，你们这样做就可以了，他们听也好，不听也好，他们信也好，不信也好，那是他们自己的事情，你们不用去在意和担心。他们反驳、指责你们，那么他们就陷入他们自己构建的言语、名字、观点、见解之中，无法解脱出来，之前如来已经对你们说过了：世间过去、现在、未来一切的物质事物、物质身体、感受、念想、行为、认识、分别、判断，描述它们的语言，它们名字的称谓，由它们建立起来的观点见解都是世间的人、众生由自己的念想、思想创建出来的，物质事物、物质身体、感受、念想、行为、认识、分别、判断本来是没有名字的，没有言语描述的，没有观点和见解的。这些言语、名字、观点都是世间的人、众生用内心的念想、思想分别、区别出来的。你们不要因为这些言语、名字、观点、见解产生烦恼和痛苦。不要陷入这些言语、名字、观点、见解的陷阱之中，不要由这些言语、名字、观点、见解生起喜怒哀乐等等的念想，就算是如来的正法也只是暂时安立出来，用来除灭世间众生的烦恼和痛苦的，是用清净的烦恼来除灭污秽的烦恼，在你们证悟解脱果位的时候，在你们进入没有烦恼和痛苦的涅槃境界的时候，连如来的正法都不会执着和挂念，连如来的正法都不会在内心中生起，念想的生起就是烦恼的生起。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',13)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
